 for col,prop,n,dtype in [(m.vertices,'co',3,np.float32),(m.loops,'vertex_index',1,np.int32),(m.corner_normals,'vector',3,np.float32),(m.uv_layers.active.data,'uv',2,np.float32)]:
  a=np.empty(len(col)*n,dtype=dtype);col.foreach_get(prop,a);h.update(a.tobytes())
