before=geometry_digest();N=512;tile=.010;rg=np.random.default_rng(16002);f=np.fft.fftfreq(N,d=tile/N);fx,fy=np.meshgrid(f,f)
def noise(length):
 a=np.fft.ifft2(np.fft.fft2(rg.normal(size=(N,N)))*np.exp(-2*math.pi**2*(length/3)**2*(fx*fx+fy*fy))).real;return(a-a.mean())/a.std()
