nm=image('rear-rim-original-normal',(normal+1)/2);orm=image('rear-rim-original-metallic-roughness',np.stack([np.ones_like(rough),rough,np.full_like(rough,.55)],-1));body=m.materials[0];body.name='Original estimated silver coating - grain and response unmeasured';body.use_nodes=True;body.node_tree.nodes.clear();n=body.node_tree.nodes;l=body.node_tree.links;p=n.new('ShaderNodeBsdfPrincipled');p.inputs['Base Color'].default_value=(.42,.45,.48,1);out=n.new('ShaderNodeOutputMaterial');l.new(p.outputs['BSDF'],out.inputs['Surface']);tex=n.new('ShaderNodeTexImage');tex.image=nm;norm=n.new('ShaderNodeNormalMap');norm.inputs['Strength'].default_value=.4;l.new(tex.outputs['Color'],norm.inputs['Color']);l.new(norm.outputs['Normal'],p.inputs['Normal']);tex=n.new('ShaderNodeTexImage');tex.image=orm;sep=n.new('ShaderNodeSeparateColor');l.new(tex.outputs['Color'],sep.inputs['Color']);l.new(sep.outputs['Green'],p.inputs['Roughness']);l.new(sep.outputs['Blue'],p.inputs['Metallic'])
inner=bpy.data.materials.new('Smoother internal envelope estimate - no certified friction seat');inner.use_nodes=True;p=inner.node_tree.nodes.get('Principled BSDF');p.inputs['Base Color'].default_value=(.42,.45,.48,1);p.inputs['Metallic'].default_value=.55;p.inputs['Roughness'].default_value=.27;m.materials.append(inner);counts=[0,0]
for face in m.polygons:
 face.material_index=1 if max(math.hypot(m.vertices[i].co.y,m.vertices[i].co.z)for i in face.vertices)<.068 else 0;counts[face.material_index]+=1
assert before==geometry_digest();bpy.ops.object.select_all(action='DESELECT');o.select_set(True);bpy.context.view_layer.objects.active=o;bpy.ops.export_scene.gltf(filepath=str(H/'rear-rim-inspection.glb'),export_format='GLB',use_selection=True,export_apply=True,export_texcoords=True,export_normals=True,export_tangents=True);bpy.ops.wm.save_as_mainfile(filepath=str(H/'rear-rim-v1.blend'),compress=True)
s=json.loads((O/'source-geometry-check.json').read_text());s['source_sha256']=sha(H/'rear-rim-v1.blend');s['export_sha256']=sha(H/'rear-rim-inspection.glb');s['source_geometry_normals_UV_preserved_at_material_stage']=before;(O/'source-geometry-check.json').write_text(json.dumps(s,indent=2)+'\n');(H/'build-report.json').write_text(json.dumps(s,indent=2)+'\n')
r={'source_sha256':s['source_sha256'],'export_sha256':s['export_sha256'],'seed':16002,'texture_size_px':[N,N],'original_periodic_data':True,'photo_pixels_used':False,'reference_height_tile_m':tile,'fine_correlation_m_estimated':.00012,'broad_correlation_m_estimated':.0008,'height_RMS_m_estimated':float(height.std()),'normal_strength':.4,'roughness_range_estimated':[float(rough.min()),float(rough.max())],'body_metallic_estimated':.55,'internal_envelope_constant_roughness':.27,'inner_normalmap_present':False,'source_triangle_counts_by_material':counts,'baseColor_linear':[.42,.45,.48],'UV_density_limits':'Caps10mm; rim128 repeats~9.6–11.1mm; hub48~8.6–10.0mm, entry and meridian charts use original author arcs.','chemistry_reflectance_or_OEM_paint_measured':False,'geometry_normals_UV_source_digest_unchanged':True,'art_accepted':False};(O/'material-build-report.json').write_text(json.dumps(r,indent=2)+'\n');print('REAR_RIM_MATERIAL',s['source_sha256'],s['export_sha256'],counts)
